  'hydration.entries': { en: 'entries', es: 'registros', fr: 'entrées', yo: 'àkọsílẹ̀', ig: 'ndeda', ha: 'bayanai', pcm: 'entries' },
  'hydration.reminderTitle': { en: 'Time to Hydrate! 💧', es: '¡Hora de hidratarte! 💧', fr: 'C’est l’heure de vous hydrater ! 💧', yo: 'Àkókò láti mu omi! 💧', ig: 'Oge iṅụ mmiri! 💧', ha: 'Lokacin shan ruwa! 💧', pcm: 'Time to drink water! 💧' },
  'hydration.reminderBody': { en: "It's been over 2 hours since your last drink. Your body needs water!", es: 'Han pasado más de 2 horas desde tu última bebida. ¡Tu cuerpo necesita agua!', fr: 'Cela fait plus de 2 heures depuis votre dernière boisson. Votre corps a besoin d’eau !', yo: 'Ó ti lé ní wákàtí méjì láti ìgbà tí o ti mu omi kẹ́yìn. Ara rẹ nílò omi!', ig: 'Ọ karịala awa 2 kemgbe ị ṅụrụ mmiri ikpeazụ. Ahụ gị chọrọ mmiri!', ha: 'Sama da awanni 2 tun lokacin da ka sha ruwa. Jikinka na buƙatar ruwa!', pcm: 'E don pass 2 hours since you last drink. Your body need water!' },
  'hydration.alertTitle': { en: 'Hydration Alert', es: 'Alerta de hidratación', fr: 'Alerte d’hydratation', yo: 'Ìkìlọ̀ Mímu Omi', ig: 'Ọkwa Mmiri Ọṅụṅụ', ha: 'Faɗakarwar Shan Ruwa', pcm: 'Hydration Alert' },
  'hydration.alertBody': { en: "You're behind on your hydration goal. Drink some water!", es: 'Vas atrasado con tu objetivo de hidratación. ¡Bebe agua!', fr: 'Vous êtes en retard sur votre objectif d’hydratation. Buvez de l’eau !', yo: 'O ti wà lẹ́yìn ibi-afẹ̀de mímu omi rẹ. Mu omi díẹ̀!', ig: 'Ị nọ n’azụ na ebumnuche mmiri gị. Ṅụọ mmiri!', ha: 'Kana baya kan manufar shan ruwanka. Sha ruwa!', pcm: 'You dey behind your water goal. Drink water!' },
  'hydration.lastRemoved': { en: 'Last entry removed', es: 'Última entrada eliminada', fr: 'Dernière entrée supprimée', yo: 'A ti yọ àkọsílẹ̀ ìkẹyìn kúrò', ig: 'Ewepụla ndeda ikpeazụ', ha: 'An cire bayanin ƙarshe', pcm: 'Last entry don remove' },
  'hydration.loadError': { en: 'Failed to load hydration data', es: 'Error al cargar los datos de hidratación', fr: 'Échec du chargement des données d’hydratation', yo: 'Kò lè gbé dátà mímu omi wọlé', ig: 'Ọ dara ịbu data mmiri', ha: 'An kasa loda bayanan shan ruwa', pcm: 'Hydration data no load' },
  'hydration.logError': { en: 'Failed to log water intake', es: 'Error al registrar el consumo de agua', fr: 'Échec de l’enregistrement de la consommation d’eau', yo: 'Kò lè kọ omi tí a mu sílẹ̀', ig: 'Ọ dara ide mmiri aṅụrụ', ha: 'An kasa rubuta shan ruwa', pcm: 'Water intake no log' },
  'hydration.removeError': { en: 'Failed to remove entry', es: 'Error al eliminar la entrada', fr: 'Échec de la suppression de l’entrée', yo: 'Kò lè yọ àkọsílẹ̀ kúrò', ig: 'Ọ dara iwepụ ndeda', ha: 'An kasa cire bayani', pcm: 'Entry no remove' },
  'hydration.energyTitle': { en: 'Hydration & Energy Connection', es: 'Conexión entre hidratación y energía', fr: 'Lien entre hydratation et énergie', yo: 'Àjọṣe Mímu Omi àti Agbára', ig: 'Njikọ Mmiri na Ike', ha: 'Alaƙar Shan Ruwa da Ƙarfi', pcm: 'Hydration & Energy Connection' },
  'hydration.tip1Title': { en: 'Peak Performance Window', es: 'Ventana de máximo rendimiento', fr: 'Fenêtre de performance optimale', yo: 'Àkókò Iṣẹ́ Gíga', ig: 'Oge Arụmọrụ Kachasị', ha: 'Lokacin Mafi Kyawun Aiki', pcm: 'Peak Performance Window' },
  'hydration.tip1Body': { en: 'Drink 500ml within 2 hours of exercise for optimal hydration.', es: 'Bebe 500 ml dentro de las 2 horas posteriores al ejercicio para una hidratación óptima.', fr: 'Buvez 500 ml dans les 2 heures suivant l’exercice pour une hydratation optimale.', yo: 'Mu 500ml láàrin wákàtí méjì eré ìdárayá fún mímu omi tó dára jù.', ig: 'Ṅụọ 500ml n’ime awa 2 nke mmega ahụ maka mmiri kacha mma.', ha: 'Sha 500ml cikin awanni 2 na motsa jiki don ingantaccen shan ruwa.', pcm: 'Drink 500ml within 2 hours of exercise for the best hydration.' },
  'hydration.tip2Title': { en: 'Metabolism Boost', es: 'Impulso al metabolismo', fr: 'Coup de pouce au métabolisme', yo: 'Ìgbélárugẹ Metabolism', ig: 'Nkwalite Metabolism', ha: 'Ƙarfafa Metabolism', pcm: 'Metabolism Boost' },
  'hydration.tip2Body': { en: 'Drinking 500ml of water can increase metabolism by 30% for 30-40 minutes.', es: 'Beber 500 ml de agua puede aumentar el metabolismo en un 30 % durante 30-40 minutos.', fr: 'Boire 500 ml d’eau peut augmenter le métabolisme de 30 % pendant 30 à 40 minutes.', yo: 'Mímu 500ml omi lè mú metabolism pọ̀si nípa 30% fún ìṣẹ́jú 30-40.', ig: 'Ịṅụ 500ml mmiri nwere ike ịbawanye metabolism site na 30% ruo nkeji 30-40.', ha: 'Shan 500ml na ruwa na iya ƙara metabolism da kashi 30% na minti 30-40.', pcm: 'Drinking 500ml water fit increase metabolism by 30% for 30-40 minutes.' },
  'hydration.tip3Title': { en: "Engineer's Tip", es: 'Consejo del ingeniero', fr: 'Astuce d’ingénieur', yo: 'Ìmọ̀ràn Ẹlẹ́rọ', ig: 'Ndụmọdụ Injinia', ha: 'Shawarar Injiniya', pcm: "Engineer's Tip" },
  'hydration.tip3Body': { en: '2% dehydration = 20% cognitive decline. Stay sharp, stay hydrated!', es: '2 % de deshidratación = 20 % de deterioro cognitivo. ¡Mantente alerta, mantente hidratado!', fr: '2 % de déshydratation = 20 % de déclin cognitif. Restez vif, restez hydraté !', yo: '2% àìní omi = 20% ìdinku ọpọlọ. Wà ní gbọ́ngbọ̀n, mu omi!', ig: '2% ụkọ mmiri = 20% mbelata uche. Nọgide na-adị nkọ, ṅụọ mmiri!', ha: '2% na ƙarancin ruwa = 20% raguwar tunani. Ka kasance mai kaifi, ka sha ruwa!', pcm: '2% dehydration = 20% brain decline. Stay sharp, stay hydrated!' },
