  'sleep.reasonDefault': { en: 'Optimal sleep window for most adults', es: 'Ventana de sueño óptima para la mayoría de los adultos', fr: 'Fenêtre de sommeil optimale pour la plupart des adultes', yo: 'Àkókò oorun tó dára jù fún ọ̀pọ̀ àgbà', ig: 'Oge ụra kacha mma maka ọtụtụ ndị okenye', ha: 'Mafi kyawun lokacin barci ga yawancin manya', pcm: 'Best sleep window for most adults' },
  'sleep.reasonGood': { en: 'Your sleep quality is good. Maintain consistency.', es: 'La calidad de tu sueño es buena. Mantén la constancia.', fr: 'La qualité de votre sommeil est bonne. Maintenez la régularité.', yo: 'Ìdára oorun rẹ dára. Pa ìdúróṣinṣin mọ́.', ig: 'Ịdị mma ụra gị dị mma. Nọgide na-emekọrịta.', ha: 'Ingancin barcinka yana da kyau. Ka ci gaba da daidaito.', pcm: 'Your sleep quality dey good. Maintain am steady.' },
  'sleep.reasonIncrease': { en: 'Increase sleep duration to improve quality.', es: 'Aumenta la duración del sueño para mejorar la calidad.', fr: 'Augmentez la durée du sommeil pour améliorer la qualité.', yo: 'Mú àkókò oorun pọ̀si láti mú ìdára dára sí.', ig: 'Bawanye oge ụra iji melite ịdị mma.', ha: 'Ƙara tsawon barci don inganta inganci.', pcm: 'Increase your sleep time make quality better.' },
